+package checkout
+
+import "testing"
+
+func TestCalculate(t *testing.T) {
+	tests := []struct {
+		name                         string
+		item, discount, tax          string
+		shipping                     ShippingMethod
+		want                         string
+	}{
+		{"standard", "100.00", "0.1", "0.05", StandardShipping, "94.50"},
+		{"expedited is taxed", "100", "0.1", "0.05", ExpeditedShipping, "110.25"},
+		{"discount excludes shipping", "100", "1", "0", ExpeditedShipping, "15.00"},
+		{"half rounds to even down", "1.005", "0", "0", StandardShipping, "1.00"},
+		{"half rounds to even up", "1.015", "0", "0", StandardShipping, "1.02"},
+		{"large exact input", "999999999999999999999999.999", "0", "0", StandardShipping, "1000000000000000000000000.00"},
+	}
+
+	calculator := CheckoutPriceCalculator{}
+	for _, test := range tests {
+		t.Run(test.name, func(t *testing.T) {
+			got, err := calculator.Calculate(test.item, test.discount, test.tax, test.shipping)
+			if err != nil || got != test.want {
+				t.Fatalf("Calculate() = %q, %v; want %q, nil", got, err, test.want)
+			}
+		})
+	}
+}
+
+func TestCalculateRejectsInvalidInput(t *testing.T) {
+	tests := []struct {
+		name                         string
+		item, discount, tax          string
+		shipping                     ShippingMethod
+	}{
+		{"empty price", "", "0", "0", StandardShipping},
+		{"negative price", "-1", "0", "0", StandardShipping},
+		{"exponent", "1e2", "0", "0", StandardShipping},
+		{"trailing decimal point", "1.", "0", "0", StandardShipping},
+		{"rate above one", "1", "1.001", "0", StandardShipping},
+		{"bad shipping", "1", "0", "0", ShippingMethod(99)},
+	}
+
+	for _, test := range tests {
+		t.Run(test.name, func(t *testing.T) {
+			if _, err := CalculateCheckoutPrice(test.item, test.discount, test.tax, test.shipping); err == nil {
+				t.Fatal("CalculateCheckoutPrice() returned nil error")
+			}
+		})
+	}
+}
